var NEIGHBORHOOD_ALIASES = {
    "Bed-Stuy": "Bedford-Stuyvesant",
    "FiDi": "Financial District",
    "LES": "Lower East Side",
    "UES": "Upper East Side",
    "UWS": "Upper West Side",
    "LIC": "Long Island City",
    "TriBeCa": "Tribeca"
};

function resolveNeighborhoodName(name) {
    return NEIGHBORHOOD_ALIASES[name] || name;
}

// ═══════════════════════════════════════════════════════
// Polygon drawing functions — MapLibre GL JS
// ═══════════════════════════════════════════════════════

function drawNeighborhoodPolygon(name, targetMap) {
    var map = targetMap || _gmap;
    if (!map) return;
    var resolved = resolveNeighborhoodName(name);
    if (_activePolygons[resolved]) return;
    var geom = NEIGHBORHOOD_POLYGONS[resolved];
    if (!geom) return;
    var slug = resolved.replace(/[^a-zA-Z0-9]/g, '-').toLowerCase();
    var sourceId = 'nb-src-' + slug;
    var fillId = 'nb-fill-' + slug;
    var lineId = 'nb-line-' + slug;
    try {
        map.addSource(sourceId, {
            type: 'geojson',
            data: { type: 'Feature', geometry: geom, properties: { name: resolved } }
        });
        map.addLayer({
            id: fillId, type: 'fill', source: sourceId,
            paint: { 'fill-color': 'rgba(196, 160, 82, 0.25)', 'fill-opacity': 0.6 }
        });
        map.addLayer({
            id: lineId, type: 'line', source: sourceId,
            paint: { 'line-color': '#B8860B', 'line-width': 2, 'line-opacity': 0.85 }
        });
        map.on('click', fillId, function(e) {
            new maplibregl.Popup({ closeButton: false, closeOnClick: true })
                .setLngLat(e.lngLat)
                .setHTML('<div style="font-weight:600;font-size:13px;padding:2px 4px;">' + resolved + '</div>')
                .addTo(map);
        });
        map.on('mouseenter', fillId, function() { map.getCanvas().style.cursor = 'pointer'; });
        map.on('mouseleave', fillId, function() { map.getCanvas().style.cursor = ''; });
        _activePolygons[resolved] = { sourceId: sourceId, fillId: fillId, lineId: lineId, map: map };
    } catch(e) { console.warn('[Polygon]', resolved, e.message); }
}

function removeNeighborhoodPolygon(name, targetMap) {
    var resolved = resolveNeighborhoodName(name);
    var entry = _activePolygons[resolved];
    if (!entry) return;
    var map = targetMap || entry.map || _gmap;
    if (!map) return;
    try {
        if (map.getLayer(entry.fillId)) map.removeLayer(entry.fillId);
        if (map.getLayer(entry.lineId)) map.removeLayer(entry.lineId);
        if (map.getSource(entry.sourceId)) map.removeSource(entry.sourceId);
    } catch(e) {}
    delete _activePolygons[resolved];
}

function toggleNeighborhoodPolygon(name, show, targetMap) {
    if (show) drawNeighborhoodPolygon(name, targetMap);
    else removeNeighborhoodPolygon(name, targetMap);
}

function clearAllNeighborhoodPolygons(targetMap) {
    Object.keys(_activePolygons).forEach(function(n) {
        removeNeighborhoodPolygon(n, targetMap);
    });
    _activePolygons = {};
}

function getActivePolygonCount() {
    return Object.keys(_activePolygons).length;
}
